//! Serves `openapi.yaml`, and keeps it honest.
//!
//! The document is embedded with `include_str!` rather than through
//! `rust_embed`, because `static/` is generated by the frontend build and wiped
//! on every `cargo build` — a spec parked there would vanish. It lives at the
//! repo root and is checked in.
//!
//! **Why serve it from the binary at all**, when the rendered docs are hosted
//! separately: this is the one thing a static docs site cannot do — describe
//! *that* instance at *that* version. For a self-hosted app a client can ask
//! its own server what it supports, rather than guessing from whatever the
//! docs site last deployed.
//!
//! The drift test below is the part that earns its keep. Rust cannot
//! introspect axum for *schemas*, but it can for *paths*, and that is the
//! mechanically checkable 80% of staying in sync.

use axum::{
    http::{header, StatusCode},
    response::IntoResponse,
};

/// The spec, baked in at compile time. Editing `openapi.yaml` triggers a
/// rebuild the same way editing any source file does.
pub const OPENAPI_YAML: &str = include_str!("../openapi.yaml");

/// GET /api/openapi.yaml — this instance's API description.
///
/// Deliberately unauthenticated. It documents the shape of the API, not any
/// data, and a client needs to read it *before* it has a credential — the
/// pairing and login flows are described in here.
pub async fn spec() -> impl IntoResponse {
    (
        StatusCode::OK,
        [
            (header::CONTENT_TYPE, "application/yaml; charset=utf-8"),
            // Version-specific content at a stable URL; let a client revalidate
            // rather than hold a stale copy across an upgrade.
            (header::CACHE_CONTROL, "public, max-age=0, must-revalidate"),
        ],
        OPENAPI_YAML,
    )
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    /// Axum 0.7 spells a path parameter `:id`; OpenAPI spells it `{id}`. Fold
    /// both to `{}` so the comparison is about *structure*, not naming — a
    /// route renamed from `:id` to `:job_id` is not a drift.
    fn normalise(path: &str) -> String {
        path.split('/')
            .map(|seg| {
                if seg.starts_with(':') || (seg.starts_with('{') && seg.ends_with('}')) {
                    "{}"
                } else if seg.starts_with('*') {
                    "*"
                } else {
                    seg
                }
            })
            .collect::<Vec<_>>()
            .join("/")
    }

    /// Every `.route("…")` literal under `src/`.
    fn router_paths() -> BTreeSet<String> {
        fn walk(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
            for entry in std::fs::read_dir(dir).expect("read src/").flatten() {
                let p = entry.path();
                if p.is_dir() {
                    walk(&p, out);
                } else if p.extension().is_some_and(|e| e == "rs") {
                    out.push(p);
                }
            }
        }
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        let mut files = Vec::new();
        walk(&root, &mut files);

        let mut paths = BTreeSet::new();
        for f in files {
            let src = std::fs::read_to_string(&f).expect("read source file");
            let mut rest = src.as_str();
            while let Some(i) = rest.find(".route(") {
                rest = &rest[i + ".route(".len()..];
                // The literal is the next quoted string, allowing for
                // whitespace and newlines between `(` and it.
                let Some(open) = rest.find('"') else { break };
                if rest[..open].contains(')') {
                    continue;
                }
                let after = &rest[open + 1..];
                let Some(close) = after.find('"') else { break };
                let literal = &after[..close];
                // Every axum route starts with a slash. The filter matters
                // because this scanner also reads *its own* source, where
                // `.route(` appears inside string literals in these tests.
                if literal.starts_with('/') {
                    paths.insert(normalise(literal));
                }
            }
        }
        paths
    }

    /// Every path key under `paths:` in the spec.
    ///
    /// Parsed by hand rather than with a YAML crate: the only thing needed is
    /// the top-level keys of one block, and adding a parser dependency to
    /// assert on 104 strings is not a trade worth making.
    fn spec_paths() -> BTreeSet<String> {
        let mut out = BTreeSet::new();
        let mut in_paths = false;
        for line in super::OPENAPI_YAML.lines() {
            if line.starts_with("paths:") {
                in_paths = true;
                continue;
            }
            if !in_paths {
                continue;
            }
            // A non-indented, non-comment line ends the block.
            if !line.starts_with(' ') && !line.trim().is_empty() && !line.starts_with('#') {
                break;
            }
            // Path keys are exactly two spaces in and start with a slash.
            let Some(rest) = line.strip_prefix("  ") else { continue };
            if rest.starts_with(' ') || !rest.starts_with('/') {
                continue;
            }
            if let Some(key) = rest.strip_suffix(':') {
                out.insert(normalise(key));
            }
        }
        out
    }

    /// The spec and the router must describe the same surface, in both
    /// directions.
    ///
    /// Undocumented endpoints are the obvious failure. The reverse — a spec
    /// path that no longer exists — is the one that actually bites: it sends a
    /// client author to an endpoint that 404s, and nothing else in the build
    /// would ever notice.
    #[test]
    fn the_spec_and_the_router_describe_the_same_api() {
        let router = router_paths();
        let spec = spec_paths();

        assert!(
            router.len() > 90,
            "route scan found only {} paths — the scanner is broken, not the spec",
            router.len()
        );

        let undocumented: Vec<_> = router.difference(&spec).collect();
        let stale: Vec<_> = spec.difference(&router).collect();

        assert!(
            undocumented.is_empty() && stale.is_empty(),
            "openapi.yaml has drifted from the router.\n\
             \n  Routed but not in the spec ({}): {:#?}\
             \n  In the spec but not routed ({}): {:#?}",
            undocumented.len(),
            undocumented,
            stale.len(),
            stale,
        );
    }

    /// The scanner is the load-bearing half of the test above; if it silently
    /// stopped matching, the drift check would pass by finding nothing.
    #[test]
    fn the_route_scanner_actually_finds_known_routes() {
        let router = router_paths();
        for expected in [
            "/health",
            "/1/submit-listens",
            "/api/v1/scrobbles",
            "/api/v1/scrobbles/{}",
            "/admin/tokens/{}/rotate",
        ] {
            assert!(router.contains(expected), "scanner missed {expected}");
        }
    }

    #[test]
    fn path_parameters_compare_by_shape_not_by_name() {
        assert_eq!(normalise("/api/v1/scrobbles/:id"), normalise("/api/v1/scrobbles/{id}"));
        assert_eq!(normalise("/api/v1/import/jobs/:job_id"), normalise("/api/v1/import/jobs/{id}"));
        assert_ne!(normalise("/api/v1/loves"), normalise("/api/v1/loves/keys"));
    }

    /// `info.version` has to move by hand, and it didn't: it read 0.41.0 while
    /// the binary shipped 0.45.0, four releases apart.
    ///
    /// That matters more here than a stale number usually would. The whole
    /// argument for serving the spec *from the binary* is that it describes
    /// **that** instance at **that** version — a client can ask its own server
    /// what it supports instead of guessing from a docs site. A version field
    /// that lies undoes exactly the property the endpoint exists for.
    ///
    /// The drift test above only compares paths, so it never noticed. This is
    /// the cheap half of the guarantee.
    ///
    /// **`Cargo.lock` has the same hazard and cannot be guarded this way.** It
    /// records this crate's own version too, and CI builds `--locked`, so a
    /// bump that is not followed by a `cargo` run fails the pipeline at its
    /// first step with "cannot update the lock file" — a message that names
    /// neither the version nor the bump. A test cannot catch it from either
    /// side: locally, `cargo test` rewrites the lock before the test compiles,
    /// and in CI `--locked` fails before any test runs. It was tried, measured
    /// doing nothing, and removed. The only thing that covers it is running
    /// `cargo check` after touching the version and committing the lock with
    /// it — so bump the version *before* the last test run, not after.
    #[test]
    fn the_spec_states_the_version_the_binary_actually_is() {
        let want = env!("CARGO_PKG_VERSION");
        // First `version:` at two-space indent — that is `info.version`. Any
        // deeper indent belongs to a schema property called "version".
        let found = super::OPENAPI_YAML
            .lines()
            .find_map(|l| l.strip_prefix("  version:"))
            .map(str::trim)
            .expect("openapi.yaml has no info.version");
        assert_eq!(
            found, want,
            "openapi.yaml says {found}, Cargo.toml says {want} — bump the spec too"
        );
    }

    /// The document has to *parse*, and for a long time it did not.
    ///
    /// Found 2026-09-13 while answering a question about one schema: two keys
    /// of the report payload were indented one level too deep, which made the
    /// whole 279-operation document unloadable by **any** YAML parser — so
    /// every client generator, linter and docs renderer failed at the first
    /// step, and nothing here noticed. Reading it by eye worked perfectly,
    /// which is exactly why it survived: the only reader was a person.
    ///
    /// The drift test above compares *paths* by scanning text and cannot see
    /// this. Neither can `cargo build` — the spec is `include_str!`d, so a
    /// syntactically broken document compiles into the binary and is served
    /// with a 200. This is the cheapest possible guard against shipping one.
    #[test]
    fn the_spec_is_a_document_a_client_can_actually_load() {
        let docs = yaml_rust2::YamlLoader::load_from_str(super::OPENAPI_YAML)
            .unwrap_or_else(|e| panic!("openapi.yaml does not parse as YAML: {e}"));
        let doc = docs.first().expect("openapi.yaml is empty");

        // Parsing is most of it, but a document that parses into something
        // other than an API description would pass that alone — an indentation
        // slip can move a whole block under the wrong key without breaking the
        // syntax, which is the half of this bug that was *not* fatal.
        let paths = doc["paths"].as_hash().expect("openapi.yaml has no paths mapping");
        assert!(paths.len() > 200, "only {} paths parsed — a block has moved", paths.len());
    }
}
